#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_deleteNode_key_in_right_subtree(void) {
    struct node* root = NULL;
    int keys[] = {50, 30, 70, 20, 40, 60, 80};
    int num_keys = sizeof(keys) / sizeof(keys[0]);

    root = helper_build_tree(keys, num_keys);
    TEST_ASSERT_NOT_NULL(root);

    int key_to_delete = 80;
    struct node* result = deleteNode(root, key_to_delete);
    TEST_ASSERT_NOT_NULL(result);

    helper_assert_tree_not_contains(result, key_to_delete);

    helper_assert_tree_inorder(result, "20 30 40 50 60 70 ");

    helper_free_tree(result);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_deleteNode_key_in_right_subtree);
    return UNITY_END();
}

